assignments.referenceSolution:
Each function is the minimal correct fix for its trap, and the tests are written so the naive version fails: a shared default list leaks `[1, 2]`, a late-binding lambda returns the last offset, an eager `chunked` hangs on an infinite iterator, and float `==` rejects `0.1 + 0.2 == 0.3`.

**`toolkit.py`**

```python
from __future__ import annotations

import heapq
import math
import re
from collections import Counter, deque
from collections.abc import Callable, Hashable, Iterable, Iterator, Sequence
from itertools import islice


def append_unique[T](item: T, bucket: list[T] | None = None) -> list[T]:
    """Append item to bucket if absent. A fresh list is created per call by default."""
    target: list[T] = [] if bucket is None else bucket
    if item not in target:
        target.append(item)
    return target


def make_adders(offsets: Sequence[int]) -> list[Callable[[int], int]]:
    """One adder per offset; each remembers its own offset (no late binding)."""
    return [lambda x, offset=offset: x + offset for offset in offsets]


def chunked[T](items: Iterable[T], size: int) -> Iterator[list[T]]:
    """Yield lists of at most `size` items from any iterable, lazily."""
    if size < 1:
        raise ValueError("size must be >= 1")
    iterator = iter(items)
    while chunk := list(islice(iterator, size)):
        yield chunk


def dedupe[H: Hashable](items: Iterable[H]) -> list[H]:
    """Remove duplicates, keeping first-seen order, in O(n)."""
    return list(dict.fromkeys(items))


def top_k_tokens(text: str, k: int) -> list[tuple[str, int]]:
    """Most frequent tokens; ties broken alphabetically for determinism."""
    if k < 0:
        raise ValueError("k must be >= 0")
    counts = Counter(re.findall(r"[a-z0-9']+", text.lower()))
    return heapq.nsmallest(k, counts.items(), key=lambda kv: (-kv[1], kv[0]))


def moving_average(values: Iterable[float], window: int) -> list[float]:
    """Trailing moving average in O(n) using a deque and a running sum."""
    if window < 1:
        raise ValueError("window must be >= 1")
    buf: deque[float] = deque()
    out: list[float] = []
    for v in values:
        buf.append(v)
        if len(buf) > window:
            buf.popleft()
        if len(buf) == window:
            out.append(math.fsum(buf) / window)
    return out


def close_enough(a: float, b: float, *, rel: float = 1e-9, abs_: float = 1e-12) -> bool:
    return math.isclose(a, b, rel_tol=rel, abs_tol=abs_)
```

**`test_toolkit.py`**

```python
from collections.abc import Iterator
from itertools import count

import pytest

from toolkit import (
    append_unique, chunked, close_enough, dedupe, make_adders, moving_average, top_k_tokens,
)


def test_append_unique_does_not_share_state_between_calls() -> None:
    assert append_unique(1) == [1]
    assert append_unique(2) == [2]  # a shared mutable default would give [1, 2]


def test_append_unique_respects_explicit_bucket() -> None:
    bucket = [1]
    assert append_unique(1, bucket) is bucket
    assert append_unique(2, bucket) == [1, 2]


def test_make_adders_bind_their_own_offset() -> None:
    adders = make_adders([1, 10, 100])
    assert [f(5) for f in adders] == [6, 15, 105]


@pytest.mark.parametrize(
    ("items", "size", "expected"),
    [
        pytest.param("abcde", 2, [["a", "b"], ["c", "d"], ["e"]], id="remainder"),
        pytest.param([], 3, [], id="empty"),
        pytest.param([1, 2, 3], 3, [[1, 2, 3]], id="exact"),
        pytest.param([1, 2], 5, [[1, 2]], id="size-larger-than-input"),
    ],
)
def test_chunked(items: object, size: int, expected: list[list[object]]) -> None:
    assert list(chunked(items, size)) == expected  # type: ignore[call-overload]


def test_chunked_is_lazy_and_accepts_iterators() -> None:
    source: Iterator[int] = count()  # infinite: would hang if chunked materialised it
    first = next(chunked(source, 3))
    assert first == [0, 1, 2]
    assert next(source) == 3  # consumed exactly one chunk


def test_chunked_rejects_bad_size() -> None:
    with pytest.raises(ValueError, match="size"):
        list(chunked([1], 0))


def test_dedupe_keeps_first_seen_order() -> None:
    assert dedupe([3, 1, 3, 2, 1]) == [3, 1, 2]
    assert dedupe([]) == []


def test_top_k_tokens_with_ties_and_edges() -> None:
    text = "the cat and The dog and the bird. And a cat!"
    assert top_k_tokens(text, 3) == [("and", 3), ("the", 3), ("cat", 2)]
    assert top_k_tokens("", 3) == []
    assert top_k_tokens("a b", 5) == [("a", 1), ("b", 1)]
    assert top_k_tokens("a b", 0) == []


def test_top_k_rejects_negative_k() -> None:
    with pytest.raises(ValueError):
        top_k_tokens("a", -1)


def test_moving_average() -> None:
    assert moving_average([1, 2, 3, 4], 2) == [1.5, 2.5, 3.5]
    assert moving_average([1, 2], 3) == []
    assert moving_average([0.1] * 10, 10) == [pytest.approx(0.1)]
    with pytest.raises(ValueError):
        moving_average([1], 0)


def test_close_enough_replaces_float_equality() -> None:
    assert 0.1 + 0.2 != 0.3
    assert close_enough(0.1 + 0.2, 0.3)
    assert not close_enough(1.0, 1.001)
```

Run `pytest -q`.
